// ImportWebsite calls the UAPI function `WPX::import_website` — Import an existing WordPress site
//
// This function imports an existing WordPress site to your cPanel account.
// The import runs in the background, so the function returns as soon as it
// queues the task.
//
//	**Note:**
//
//	- This function has the following prerequisites:
//	    - The `nova-wordpress` entitlement.
//	    - The `redirects`, `wp-toolkit`, and `mysql` features.
//	- Because the request carries the source WordPress credentials, use the
//	  `POST` method and do not place the `source_password` or `source_user`
//	  keys in the URL query string. The system rejects a request that uses
//	  another method, or that puts either key in the query string, before it
//	  reads the credentials, so they cannot leak into access logs, proxy
//	  logs, or browser history.
//	- The background task can still fail after this function returns, for
//	  example when a feature is revoked in the meantime. Read the outcome
//	  from the `WPX::get_task_progress` function.
//
// This function requires an HTTP POST request.
//
// Available since cPanel & WHM version 137.
//
// Documentation: https://api.docs.cpanel.net/specifications/cpanel.openapi/wpx/wpx-import_website.md
func (c *WpxClient) ImportWebsite(ctx context.Context, extra ...cpanel.Args) (*cpanel.UAPIResult[WpxImportWebsiteData], error) {
	return cpanel.UAPICall[WpxImportWebsiteData](ctx, c.c, http.MethodPost, "WPX", "import_website", cpanel.CombineArgs(extra...))
}

